import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    customer_profile = inputs["customer_profile"].copy()
    profile_changes = inputs["profile_changes"].copy()

    # Handle empty inputs
    if profile_changes.empty:
        return {"new_profile": customer_profile[["customer_id", "email", "phone", "tier", "updated_seq"]]}

    # Ensure proper types
    customer_profile["customer_id"] = customer_profile["customer_id"].astype("int64")
    customer_profile["updated_seq"] = customer_profile["updated_seq"].astype("int64")
    profile_changes["customer_id"] = profile_changes["customer_id"].astype("int64")
    profile_changes["change_seq"] = profile_changes["change_seq"].astype("int64")

    # Convert profile data to dict keyed by customer_id for easier updates
    profile_dict = {}
    for _, row in customer_profile.iterrows():
        cid = row["customer_id"]
        profile_dict[cid] = {
            "email": row["email"],
            "phone": row["phone"],
            "tier": row["tier"],
            "updated_seq": row["updated_seq"]
        }

    # Sort changes by customer_id, then by change_seq for deterministic processing
    profile_changes = profile_changes.sort_values(["customer_id", "change_seq"]).reset_index(drop=True)

    # Process each change
    for _, change_row in profile_changes.iterrows():
        cid = change_row["customer_id"]
        change_seq = change_row["change_seq"]

        # Check if customer exists
        if cid in profile_dict:
            existing = profile_dict[cid]
            # Skip if change_seq <= updated_seq
            if change_seq <= existing["updated_seq"]:
                continue

            # Save original state for no-op detection
            original_state = existing.copy()

            # Apply the three field rules
            email_val = change_row["email"]
            if pd.notna(email_val):
                if email_val == "<<NULL>>":
                    existing["email"] = None
                else:
                    existing["email"] = email_val.lower().strip()

            phone_val = change_row["phone"]
            if pd.notna(phone_val):
                if phone_val == "<<NULL>>":
                    existing["phone"] = None
                else:
                    existing["phone"] = phone_val

            tier_val = change_row["tier"]
            if pd.notna(tier_val):
                if tier_val == "<<NULL>>":
                    existing["tier"] = None
                else:
                    existing["tier"] = tier_val

            # Check if row is identical (NULL-safe comparison)
            is_identical = (
                (original_state["email"] is existing["email"] or 
                 (original_state["email"] == existing["email"])) and
                (original_state["phone"] is existing["phone"] or 
                 (original_state["phone"] == existing["phone"])) and
                (original_state["tier"] is existing["tier"] or 
                 (original_state["tier"] == existing["tier"]))
            )

            if not is_identical:
                existing["updated_seq"] = change_seq
        else:
            # Customer does not exist: create new row
            email_val = change_row["email"]
            if pd.notna(email_val) and email_val != "<<NULL>>":
                email = email_val.lower().strip()
            else:
                email = None

            phone_val = change_row["phone"]
            if pd.notna(phone_val) and phone_val != "<<NULL>>":
                phone = phone_val
            else:
                phone = None

            tier_val = change_row["tier"]
            if pd.notna(tier_val) and tier_val != "<<NULL>>":
                tier = tier_val
            else:
                tier = None

            profile_dict[cid] = {
                "email": email,
                "phone": phone,
                "tier": tier,
                "updated_seq": change_seq
            }

    # Convert back to DataFrame
    result_rows = []
    for cid in sorted(profile_dict.keys()):
        row = profile_dict[cid]
        result_rows.append({
            "customer_id": cid,
            "email": row["email"],
            "phone": row["phone"],
            "tier": row["tier"],
            "updated_seq": row["updated_seq"]
        })

    new_profile = pd.DataFrame(result_rows)

    # Ensure proper types
    if not new_profile.empty:
        new_profile["customer_id"] = new_profile["customer_id"].astype("int64")
        new_profile["updated_seq"] = new_profile["updated_seq"].astype("int64")

    return {"new_profile": new_profile}
